import { createRequire } from "node:module";
import { dirname, join } from "node:path";

const require = createRequire(import.meta.url);
const viewing = new Set(["selectTab", "setVisible", "screenshot"]);
const input = new Set([
  "navigate",
  "back",
  "forward",
  "reload",
  "mousemove",
  "mousedown",
  "mouseup",
  "wheel",
  "keydown",
  "keyup",
  "newTab",
  "closeTab",
]);

/** Existing Playwright dashboard, scoped to this Run's actual context. */
export async function createBrowserDashboard(
  context,
  control,
  { library = dirname(require.resolve("playwright-core/package.json")) } = {},
) {
  // eslint-disable-next-line no-restricted-syntax -- Fixed generated embedding entry in the host-selected, pinned Playwright package; never a tool-supplied module.
  const { tools } = require(join(library, "lib/kaijan-dashboard.cjs"));
  const held = new Map();
  const requests = new Map();
  const initialSelections = new WeakMap();
  let inputPage;
  let connected = false;
  const selectedPage = () =>
    inputPage && !inputPage.isClosed()
      ? inputPage
      : context.pages().find((page) => !page.isClosed());
  const restoreSelection = (connection) => {
    if (!initialSelections.has(connection)) {
      const page = selectedPage();
      initialSelections.set(
        connection,
        page
          ? connection.selectTab({
              browser: context.browser()._guid,
              context: context._guid,
              page: page._guid,
            })
          : Promise.resolve(),
      );
    }
    return initialSelections.get(connection);
  };
  const releaseInput = async () => {
    for (const [page, { keys, buttons }] of held) {
      if (page && !page.isClosed()) {
        for (const key of keys) await page.keyboard.up(key);
        for (const button of buttons) await page.mouse.up({ button });
      }
      held.delete(page);
    }
  };
  const server = await tools.createKaijanDashboard(context, {
    host: "127.0.0.1",
    port: 0,
    assetsDir: join(library, "lib/vite/kaijan-dashboard"),
    onDisconnect: () => {
      connected = false;
      control.disconnect();
    },
    dispatch: async (method, params, next, connection) => {
      connected = true;
      if (method === "kaijanControl") {
        // Upstream attaches the first tab on each connection. Restore the
        // person's selected tab before reporting readiness or admitting input.
        await restoreSelection(connection);
        if (params.mode === "status") return control.status();
        if (!["human", "agent"].includes(params.mode))
          throw Error("Unknown browser control mode");
        if (!requests.has(params.requestId))
          requests.set(params.requestId, control.status().generation);
        const generation = requests.get(params.requestId);
        const receipt = await (params.mode === "human"
          ? control.takeOver(params.requestId, generation)
          : control.resume(params.requestId, generation));
        // The last viewer can disappear while an admitted native action drains.
        // A late acknowledgment must not leave a disconnected human owner.
        if (!connected) control.disconnect();
        return receipt;
      }
      if (viewing.has(method)) {
        await restoreSelection(connection);
        const value = await next();
        if (method === "selectTab")
          inputPage = context
            .pages()
            .find((page) => page._guid === params.page);
        return value;
      }
      // The upstream dispatcher also contains local-file/debugger functions.
      // Only the browser viewing/interaction surface belongs to this feature.
      if (!input.has(method))
        throw Error("This action is unavailable in the Run viewer");
      await restoreSelection(connection);
      return control.human(control.status().generation, async () => {
        inputPage = connection._attachedPage?.page;
        let pressed = held.get(inputPage);
        if (!pressed)
          held.set(
            inputPage,
            (pressed = { keys: new Set(), buttons: new Set() }),
          );
        // Remember admitted downs even when their acknowledgment is lost.
        if (method === "keydown") pressed.keys.add(params.key);
        if (method === "mousedown")
          pressed.buttons.add(params.button || "left");
        const result = await next();
        inputPage = connection._attachedPage?.page;
        if (method === "keyup") pressed.keys.delete(params.key);
        if (method === "mouseup")
          pressed.buttons.delete(params.button || "left");
        return result;
      });
    },
  });
  return { ...server, releaseInput, selectedPage };
}
